let shaderProgram;
const numFunctionsMax = 2;
const functionNames = ["sin", "cos", "abs_sin", "heart", "snowflake", "spiral", "inverted_spiral", "flower", "mandala", "electric_web", "fractal_tree"];
let functions = [];

const fixedFunctionTypes = [0, 1]; // 0: sin, 1: cos

const vertShader = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  gl_Position = vec4(aPosition, 1.0);
}
`;

const fragShader = `
precision highp float;

varying vec2 vTexCoord;

uniform vec2 u_resolution;
uniform int u_numFunctions;

uniform int u_functionTypes[2];
uniform float u_freqX[2];
uniform float u_freqY[2];
uniform float u_amp[2];
uniform float u_offset[2];
uniform float u_animationProgress;
uniform float u_transitionProgress;


// Function to convert HSL to RGB
float hue2rgb(float p, float q, float t) {
  if (t < 0.0) t += 1.0;
  if (t > 1.0) t -= 1.0;
  if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
  if (t < 1.0 / 2.0) return q;
  if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
  return p;
}

vec3 hsl2rgb(float h, float s, float l) {
    float r = l;
    float g = l;
    float b = l;
    if (s != 0.0) {
      float q = l < 0.5 ? l * (1.0 + s) : l + s - l * s;
      float p = 2.0 * l - q;
      r = hue2rgb(p, q, h + 1.0 / 3.0);
      g = hue2rgb(p, q, h);
      b = hue2rgb(p, q, h - 1.0 / 3.0);
    }
    return vec3(r, g, b);
}

// Function to get color from the predefined winter palette
vec3 getColor(float t){
    // Define the palette with normalized RGB values
    vec3 color0 = vec3(0.792, 0.941, 0.972); // caf0f8
    vec3 color1 = vec3(0.678, 0.909, 0.957); // ade8f4
    vec3 color2 = vec3(0.565, 0.878, 0.941); // 90e0ef
    vec3 color3 = vec3(0.282, 0.792, 0.894); // 48cae4
    vec3 color4 = vec3(0.0, 0.706, 0.847);   // 00b4d8
    vec3 color5 = vec3(0.0, 0.706, 0.847);   // 00b4d8
    vec3 color6 = vec3(0.0, 0.588, 0.780);   // 0096c7
    vec3 color7 = vec3(0.0, 0.467, 0.714);   // 0077b6
    vec3 color8 = vec3(0.008, 0.243, 0.541); // 023e8a
    vec3 color9 = vec3(0.012, 0.016, 0.369); // 03045e

    // Normalize t to [0,1)
    t = fract(t);

    float segment = 1.0 / 9.0;
    float idx = floor(t / segment);
    float localT = (t - idx * segment) / segment;

    if(idx >= 9.0){
        idx = 8.0;
        localT = 1.0;
    }

    if(idx == 0.0){
        return mix(color0, color1, localT);
    }
    else if(idx == 1.0){
        return mix(color1, color2, localT);
    }
    else if(idx == 2.0){
        return mix(color2, color3, localT);
    }
    else if(idx == 3.0){
        return mix(color3, color4, localT);
    }
    else if(idx == 4.0){
        return mix(color4, color5, localT);
    }
    else if(idx == 5.0){
        return mix(color5, color6, localT);
    }
    else if(idx == 6.0){
        return mix(color6, color7, localT);
    }
    else if(idx == 7.0){
        return mix(color7, color8, localT);
    }
    else { // idx ==8
        return mix(color8, color9, localT);
    }
}

// Enhanced applyFunction with frequency parameters
float applyFunction(int type, float x, float y, float freqX, float freqY) {
  if (type == 0) return sin(x); // base gradient
  if (type == 1) return cos(y); // ice layer
  if (type == 2) return abs(sin(x * freqX)); // vertical lines for cracks
   if (type == 3) { 
    float x2 = x * x;
    float y2 = y * y;
    return pow(x2 + y2 - 1.0, 3.0) - x2 * pow(y, 3.0);
  }
  if (type == 4) {
    float angle = atan(y, x);
    float radius = sqrt(x * x + y * y);
    return abs(sin(radius * freqX) * cos(6.0 * angle));
  }
    if (type == 5) {
    float r = sqrt(x * x + y * y);
    float angle = atan(y, x);
    return sin(freqX * r  + freqY * angle * 10.0 );
  }
   if (type == 6) {
    float r = sqrt(x * x + y * y);
    float angle = atan(y, x);
    return sin(freqX * 1.0 / r + freqY * angle * 10.0);
  }
  if (type == 7) {
    float r = sqrt(x * x + y * y);
    float angle = atan(y, x);
    return sin(6.0 * angle + r * freqX) * cos(r * freqY);
  }
  if (type == 8) {
    float r = sqrt(x * x + y * y);
    float angle = atan(y, x);
    return cos(10.0 * angle + r * freqX) * cos(10.0 * r);
  }
  if (type == 9) {
    return abs(sin(x * freqX) * cos(y * freqY)) * abs(sin(y * freqX) * cos(x * freqY));
  }
  if (type == 10) {
    float angle = atan(y, x);
    float r = sqrt(x * x + y * y);
    return abs(sin(2.0 * r * freqX) * cos(2.0 * angle * freqY));
  }
  return 0.0;
}

// Integer Modulo function
int mod_int(int a, int b) {
  return a - b * (a / b);
}


void main() {
  float aspect = u_resolution.x / u_resolution.y;

  vec2 uv = vTexCoord * 2.0 - 1.0;
  uv.x *= aspect;

  float scaleFactor = 6.0;

  float mappedX = uv.x * scaleFactor * 3.141592653589793;
  float mappedY = uv.y * scaleFactor * 3.141592653589793;

  float patternBase = 0.0;
  float patternIce = 0.0;


  float t = u_animationProgress;
  float transitionT = u_transitionProgress;

  for(int i = 0; i < 2; i++) {
    float inputX = mappedX * u_freqX[i];
    float inputY = mappedY * u_freqY[i];

    float funcVal = 0.0;
     int prevType = u_functionTypes[i];
     int nextType = u_functionTypes[i];
      if(transitionT < 0.5){

            if (u_functionTypes[i] < 10) nextType = mod_int((u_functionTypes[i] + 1), 11); //cycle through functions
            else nextType = 0;

            funcVal = mix(applyFunction(prevType, inputX, inputY, u_freqX[i], u_freqY[i]), applyFunction(nextType, inputX, inputY, u_freqX[i], u_freqY[i]), transitionT * 2.0);
        }
        else if(transitionT < 1.0)
        {

            if (u_functionTypes[i] < 10) nextType = mod_int((u_functionTypes[i] + 1), 11);
            else nextType = 0;
            funcVal = mix(applyFunction(nextType, inputX, inputY, u_freqX[i], u_freqY[i]), applyFunction(prevType, inputX, inputY, u_freqX[i], u_freqY[i]), (transitionT - 0.5) * 2.0);
         } else {
             funcVal = applyFunction(prevType, inputX, inputY, u_freqX[i], u_freqY[i]);
         }

    float calcValue = funcVal * u_amp[i] + u_offset[i];

    if(i == 0){
        patternBase += calcValue;
      }
      if(i == 1){
        patternIce += calcValue;
      }

  }

  // Normalize patternBase and patternIce
  float normalizedBase = (patternBase + 1.0) / 2.0; // assuming sin ranges -1 to 1
  float normalizedIce = (patternIce + 1.0) / 2.0;   // assuming cos ranges -1 to 1

  // Combine base and ice
  float combinedPattern = normalizedBase * 0.6 + normalizedIce * 0.4;


  // Define base colors from palette
  vec3 baseColor = getColor(combinedPattern);


  // Apply the crack pattern to the ice layer
    vec3 finalColor = baseColor;

   // Add some subtle color variation based on crack pattern
   //float subtleColorVariation = smoothstep(0.0, 0.5, normalizedCracks);
   vec3 variedColor = finalColor;


  gl_FragColor = vec4(variedColor, 1.0);
}
`;

